import React from 'react';
import { motion } from 'framer-motion';
import SplitReveal from './SplitReveal';
import { fadeInUpVariant, metaVariant, scrollViewport } from '../config/motion';

/**
 * Shared section header: index + tag, display title, optional description.
 * The index number is generated by a CSS counter (see `.section-num` in styles.css),
 * so sections are always numbered in reading order.
 *
 * Choreography: meta row slides in → title words rise from a mask → description fades up.
 */
export default function SectionHeader({
  tag,
  title,
  description,
  motionEnabled = true,
  compact = false,
  className = '',
}) {
  const classes = `section-header${compact ? ' section-header--compact' : ''}${className ? ` ${className}` : ''}`;

  const meta = (
    <>
      <span className="section-num" aria-hidden="true" />
      <span className="section-tag">{tag}</span>
    </>
  );

  if (!motionEnabled) {
    return (
      <div className={classes}>
        <div className="section-meta">{meta}</div>
        {title && <h2 className="section-title">{title}</h2>}
        {description && <p className="section-desc">{description}</p>}
      </div>
    );
  }

  return (
    <motion.div
      className={classes}
      initial="hidden"
      whileInView="visible"
      viewport={scrollViewport}
      variants={{ hidden: {}, visible: { transition: { staggerChildren: 0.12 } } }}
    >
      <motion.div className="section-meta" variants={metaVariant}>
        {meta}
      </motion.div>
      {title && (
        <SplitReveal as="h2" className="section-title" motionEnabled stagger={0.07}>
          {title}
        </SplitReveal>
      )}
      {description && (
        <motion.p className="section-desc" variants={fadeInUpVariant}>
          {description}
        </motion.p>
      )}
    </motion.div>
  );
}
